// Turns the instruction table into the Markdown reference in docs/INSTRUCTIONS.md.
// Run `npm run docs` to regenerate it. A test fails if the file goes out of date.

import { INSTRUCTIONS, groupByMnemonic } from "./instructions.js";

function describeOperands(instruction) {
  if (instruction.operands.length === 0) return "none";
  return instruction.operands.map((operand) => `\`${operand.name}\` (${operand.kind})`).join(", ");
}

export function renderInstructionReference(list = INSTRUCTIONS) {
  const lines = [
    "# Twist instruction reference",
    "",
    "<!-- Generated by `npm run docs` from src/language/instructions.js. Do not edit by hand. -->",
    "",
    "Instructions that share two letters (like `ps1`, `ps2` and `ps3`) are **not**",
    "variations of each other. Each code is its own instruction, and the number",
    "never tells you what it does.",
    "",
    "## All instructions",
    "",
    "| Code | Name | Category | Operands | What it does | Example |",
    "| --- | --- | --- | --- | --- | --- |",
  ];

  for (const instruction of list) {
    lines.push(
      `| \`${instruction.code}\` | ${instruction.name} | ${instruction.category} | ` +
        `${describeOperands(instruction)} | ${instruction.summary} | \`${instruction.example}\` |`,
    );
  }

  lines.push("", "## Same letters, different jobs", "");

  for (const [mnemonic, group] of groupByMnemonic(list)) {
    const parts = group.map((instruction) => `\`${instruction.code}\` ${instruction.name}`);
    lines.push(`- **${mnemonic}**: ${parts.join(", ")}`);
  }

  return `${lines.join("\n")}\n`;
}
